# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>
#include <c10/util/Optional.h>

torch::Tensor conv3x3_forward(
    torch::Tensor x,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int64_t padding
);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv3x3_forward", &conv3x3_forward, "Specialized 3x3 NCHW float32 conv forward");
