CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <c10/util/Optional.h>

// Specialized 3x3 direct convolution kernel for NCHW float32, stride=1, dilation=1, groups=1.
// Each thread computes one output element.
// Block: (BW, BH) over (W_out, H_out), grid: (ceil(W_out/BW), ceil(H_out/BH), N*C_out)

#define BW 32
#define BH 8

__global__ void conv3x3_kernel(
    const float* __restrict__ input,   // [N, C_in, H_in, W_in]
    const float* __restrict__ weight,  // [C_out, C_in, 3, 3]
    const float* __restrict__ bias,    // [C_out] or nullptr
    float* __restrict__ output,        // [N, C_out, H_out, W_out]
    int N, int C_in, int H_in, int W_in,
    int C_out, int H_out, int W_out,
    int padding
) {
    int ow = blockIdx.x * BW + threadIdx.x;
    int oh = blockIdx.y * BH + threadIdx.y;
    int nc_out = blockIdx.z;  // combined index: n * C_out + c_out
    int n = nc_out / C_out;
    int c_out = nc_out % C_out;

    if (ow >= W_out || oh >= H_out) return;

    float acc = (bias != nullptr) ? bias[c_out] : 0.0f;

    const float* w_ptr = weight + c_out * C_in * 9;
    const float* in_ptr = input + n * C_in * H_in * W_in;

    int ih_base = oh - padding;
    int iw_base = ow - padding;

    for (int c = 0; c < C_in; ++c) {
        const float* in_c = in_ptr + c * H_in * W_in;
        const float* w_c  = w_ptr  + c * 9;

        // Unrolled 3x3
        int ih0 = ih_base + 0, ih1 = ih_base + 1, ih2 = ih_base + 2;
        int iw0 = iw_base + 0, iw1 = iw_base + 1, iw2 = iw_base + 2;

        bool v0 = (ih0 >= 0 && ih0 < H_in);
        bool v1 = (ih1 >= 0 && ih1 < H_in);
        bool v2 = (ih2 >= 0 && ih2 < H_in);
        bool h0 = (iw0 >= 0 && iw0 < W_in);
        bool h1 = (iw1 >= 0 && iw1 < W_in);
        bool h2 = (iw2 >= 0 && iw2 < W_in);

        if (v0) {
            int row0 = ih0 * W_in;
            if (h0) acc += in_c[row0 + iw0] * w_c[0];
            if (h1) acc += in_c[row0 + iw1] * w_c[1];
            if (h2) acc += in_c[row0 + iw2] * w_c[2];
        }
        if (v1) {
            int row1 = ih1 * W_in;
            if (h0) acc += in_c[row1 + iw0] * w_c[3];
            if (h1) acc += in_c[row1 + iw1] * w_c[4];
            if (h2) acc += in_c[row1 + iw2] * w_c[5];
        }
        if (v2) {
            int row2 = ih2 * W_in;
            if (h0) acc += in_c[row2 + iw0] * w_c[6];
            if (h1) acc += in_c[row2 + iw1] * w_c[7];
            if (h2) acc += in_c[row2 + iw2] * w_c[8];
        }
    }

    output[nc_out * H_out * W_out + oh * W_out + ow] = acc;
}

torch::Tensor conv3x3_forward(
    torch::Tensor x,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int64_t padding
) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");

    int N    = x.size(0);
    int C_in = x.size(1);
    int H_in = x.size(2);
    int W_in = x.size(3);
    int C_out = weight.size(0);
    int H_out = H_in + 2 * padding - 2;  // stride=1, dilation=1, kernel=3
    int W_out = W_in + 2 * padding - 2;

    auto output = torch::empty({N, C_out, H_out, W_out}, x.options());

    const float* bias_ptr = nullptr;
    if (bias.has_value() && bias.value().defined()) {
        bias_ptr = bias.value().data_ptr<float>();
    }

    dim3 block(BW, BH);
    dim3 grid(
        (W_out + BW - 1) / BW,
        (H_out + BH - 1) / BH,
        N * C_out
    );

    conv3x3_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, C_in, H_in, W_in,
        C_out, H_out, W_out,
        (int)padding
    );

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Performs a standard 2D convolution operation with an asymmetric input and a square kernel.

        Args:
            in_channels (int): Number of channels in the input tensor.
            out_channels (int): Number of channels produced by the convolution.
            kernel_size (int): Size of the square convolution kernel.
            stride (int, optional): Stride of the convolution. Defaults to 1.
            padding (int, optional): Padding applied to the input. Defaults to 0.
            dilation (int, optional): Spacing between kernel elements. Defaults to 1.
            groups (int, optional): Number of blocked connections from input channels to output channels. Defaults to 1.
            bias (bool, optional): If `True`, adds a learnable bias to the output. Defaults to `False`.
        """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.conv2d = nn.Conv2d(in_channels, out_channels, (kernel_size, kernel_size), stride=stride, padding=padding, dilation=dilation, groups=groups, bias=bias)
        # <<<END_IMPROVE>>>

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Performs the 2D convolution.

                Args:
                    x (torch.Tensor): Input tensor of shape (batch_size, in_channels, height, width).

                Returns:
                    torch.Tensor: Output tensor of shape (batch_size, out_channels, height_out, width_out).
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        use_fast = (
        x.is_cuda and
        x.dtype == torch.float32 and
        self.conv2d.weight.dtype == torch.float32 and
        self.conv2d.kernel_size == (3, 3) and
        self.conv2d.stride == (1, 1) and
        self.conv2d.dilation == (1, 1) and
        self.conv2d.groups == 1 and
        self.conv2d.weight.is_cuda
        )
        if use_fast:
            return _stark_get_extension().conv3x3_forward(
            x.contiguous(),
            self.conv2d.weight.contiguous(),
            self.conv2d.bias,
            self.conv2d.padding[0]
            )
        return self.conv2d(x)
        # <<<END_IMPROVE>>>

